ALTER TABLE "CollaborationPayment" ADD CONSTRAINT "CollaborationPayment_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CollaborationPayment" ADD CONSTRAINT "CollaborationPayment_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "BusinessProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CollaborationPayment" ADD CONSTRAINT "CollaborationPayment_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "CreatorProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CreatorTransfer" ADD CONSTRAINT "CreatorTransfer_collaborationPaymentId_fkey" FOREIGN KEY ("collaborationPaymentId") REFERENCES "CollaborationPayment"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CreatorTransfer" ADD CONSTRAINT "CreatorTransfer_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "CreatorProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CollaborationRefund" ADD CONSTRAINT "CollaborationRefund_collaborationPaymentId_fkey" FOREIGN KEY ("collaborationPaymentId") REFERENCES "CollaborationPayment"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "CollaborationRefund" ADD CONSTRAINT "CollaborationRefund_requestedByUserId_fkey" FOREIGN KEY ("requestedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CollaborationRefund" ADD CONSTRAINT "CollaborationRefund_approvedByAdminId_fkey" FOREIGN KEY ("approvedByAdminId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PaymentIssue" ADD CONSTRAINT "PaymentIssue_campaignParticipantId_fkey" FOREIGN KEY ("campaignParticipantId") REFERENCES "CampaignParticipant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PaymentIssue" ADD CONSTRAINT "PaymentIssue_collaborationPaymentId_fkey" FOREIGN KEY ("collaborationPaymentId") REFERENCES "CollaborationPayment"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PaymentIssue" ADD CONSTRAINT "PaymentIssue_openedByUserId_fkey" FOREIGN KEY ("openedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
